// Basic conditional: if T is a Promise, unwrap it; else keep T
type Unwrap<T> = T extends Promise<infer U> ? Unwrap<U> : T;

// Tests:
type A = Unwrap<Promise<string>>;            // string
type B = Unwrap<Promise<Promise<number>>>;    // number
type C = Unwrap<string>;                     // string (already unwrapped)

// More powerful: extract the element type from any iterable
type ElementOf<T> =
  T extends ReadonlyArray<infer E> ? E :
  T extends Set<infer E> ? E :
  T extends Map<any, infer E> ? E :
  never;

type DocIds = ElementOf<string[]>;       // string
type TokenSet = ElementOf<Set<number>>;  // number
type MetaVal = ElementOf<Map<string, { score: number }>>; // { score: number }

// Extract the first argument type of any function
type FirstArg<T> = T extends (first: infer A, ...rest: any[]) => any ? A : never;

type Handler = (event: MouseEvent, context: { userId: string }) => void;
type HandlerFirstArg = FirstArg<Handler>; // MouseEvent

// Extract a tuple's head and tail
type Head<T extends any[]> = T extends [infer H, ...any[]] ? H : never;
type Tail<T extends any[]> = T extends [any, ...infer T] ? T : never;

type Coords = [number, number, string];
type X = Head<Coords>;  // number
type Rest = Tail<Coords>; // [number, string]

// Practical: extract the item type from useQuery's return type
import type { UseQueryResult } from '@tanstack/react-query';
type QueryData<T extends UseQueryResult<any, any>> =
  T extends UseQueryResult<infer D, any> ? D : never;

// If useConversations() returns UseQueryResult<Conversation[], Error>
// QueryData<ReturnType<typeof useConversations>> = Conversation[]

// NonNullable<T> is defined as: T extends null | undefined ? never : T
// The distribution happens automatically over union types
type NonNullable<T> = T extends null | undefined ? never : T;

// Distributed over union: each member evaluated independently
type Clean = NonNullable<string | null | undefined | number>;
// = string | number (null and undefined became never, collapsed)

// Turn off distribution with tuple wrapping [T] when you DON'T want distribution
type IsString<T> = T extends string ? true : false;
type D1 = IsString<string | number>; // boolean (distributed: true | false)

type IsStringExact<T> = [T] extends [string] ? true : false;
type D2 = IsStringExact<string | number>; // false (union as whole, not distributed)

type AgentPhase = 'retrieval' | 'reasoning' | 'generation';
type EventKind = 'start' | 'progress' | 'complete' | 'error';

// Cartesian product of all combinations
type AgentEventType = `agent.${AgentPhase}.${EventKind}`;
// = 'agent.retrieval.start' | 'agent.retrieval.progress' | ... (12 combinations)

interface AgentEvent {
  type: AgentEventType;
  timestamp: number;
  payload: unknown;
}

// TypeScript now catches typos at compile time:
const evt: AgentEvent = {
  type: 'agent.retrieval.start', // ✅ valid
  timestamp: Date.now(),
  payload: { query: 'AI policy' }
};
// type: 'agent.retrievel.start' // ❌ compile error - typo caught

// Capitalize / Uppercase / Lowercase / Uncapitalize for string manipulation
type EventKey = 'onSuccess' | 'onError' | 'onPending';
type HandlerName = `handle${Capitalize<EventKey>}`;
// = 'handleOnSuccess' | 'handleOnError' | 'handleOnPending'
